  anotherPlace: b.anotherPlace || "",
  bathroom: b.bathroom || "",
  diningRoom: b.diningRoom || "",
  kitchen: b.kitchen || "",
  livingRoom: b.livingRoom || "",
  garage: b.garage || "",
  mainBedroom: b.mainBedroom || "",
  secondBedroom: b.secondBedroom || "",
  plants: b.plants || "",
  startDate: b.startDate || "",
  zone: b.zone || "",
  comments: b.comments || "",
  source: b.source || "wizardForm",
  status: "nuevo",
  question_index: 0,
  cualificado: "",
  razon_no_cual: "",
  etapa_seg: "",
