  ultimo_msg_ts: "",
  calendar_event_id: "",
  notas: ""
};

const now = $now.setZone("America/Argentina/Buenos_Aires");
const weekday = now.weekday;
const hour = now.hour;
const laboral = (weekday >= 1 && weekday <= 5) && (hour >= 8 && hour < 18);

return [{ json: { lead, laboral, hour, weekday } }];

